function robotVisual(kind='advertising',slot=kind,extra=''){
  const photoDefaults={advertising:'/assets/site-photos/advertising-robot.jpeg',serving:'/assets/site-photos/serving-robot.jpeg',companion:'/assets/site-photos/companion-robot.jpeg'};
  const src=siteContent.images?.[slot]||photoDefaults[slot];
  if(src)return `<div class="robot ${extra}"><img class="uploaded-robot" src="${esc(src)}" alt="${esc(robots[kind]?.name||'ZEVON robot')}" loading="lazy"></div>`;
  return robotArt(kind,extra);
}
