function venueArtwork(key,a,b,scene,index){const photo=venuePhotos[scene];return `<div class="venue-art${photo?' has-photo':''}" role="img" aria-label="${esc(scene)} venue scene featuring a ZEVON robot">${photo?`<img class="venue-photo" src="${photo}" alt="" loading="lazy">`:`<svg class="venue-backdrop" viewBox="0 0 1000 500" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="venue-bg-${index}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient><linearGradient id="venue-floor-${index}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#f4e7c9" stop-opacity=".02"/><stop offset="1" stop-color="#081713" stop-opacity=".55"/></linearGradient></defs><rect width="1000" height="500" fill="url(#venue-bg-${index})"/><circle cx="760" cy="125" r="220" fill="#e9cf91" opacity=".06"/><circle cx="220" cy="90" r="170" fill="#d6e6d9" opacity=".05"/>${venueScenes[scene]}<path d="M0 390 Q280 360 500 390 T1000 385V500H0Z" fill="url(#venue-floor-${index})"/><path d="M0 435 Q260 397 500 425 T1000 418" fill="none" stroke="#f0d9a7" stroke-width="2" opacity=".22"/></svg><div class="venue-robot" aria-hidden="true">${robotArt(key)}</div>`}<div class="venue-vignette"></div></div>`;}

function brand(){return `<a class="brand" href="/" aria-label="ZEVON Entertainment home"><span class="brand-mark">Z↗</span><span><span class="brand-name">ZEVON</span><span class="brand-sub">ENTERTAINMENT</span></span></a>`;}
function header(active){return `<header class="site-header"><div class="nav-shell">${brand()}<nav class="nav-links" id="nav-links" aria-label="Main navigation">${routes.map(([n,u])=>`<a href="${u}" class="${active===u?'active':''}">${n}</a>`).join('')}</nav><div class="nav-actions"><a class="btn header-cta" href="/contact?subject=Book%20a%20Demo">Book a Demo&nbsp; ↗</a><button class="menu-toggle" aria-label="Open menu" aria-expanded="false" id="menu-toggle">☰</button></div></div></header>`;}
function footer(){return `<footer class="site-footer"><div class="container"><div class="footer-grid"><div class="footer-brand">${brand()}<p class="footer-blurb">Premium autonomous robots for advertising, hospitality and customer engagement — available for events, businesses and everyday operations in between.</p><div class="social-links footer-social" aria-label="Follow ZEVON on social media"><a href="https://www.youtube.com/" target="_blank" rel="noopener noreferrer" aria-label="ZEVON on YouTube demo link"><b>▶</b></a><a href="https://www.linkedin.com/" target="_blank" rel="noopener noreferrer" aria-label="ZEVON on LinkedIn demo link"><b>in</b></a><a href="https://www.instagram.com/" target="_blank" rel="noopener noreferrer" aria-label="ZEVON on Instagram demo link"><b>◎</b></a></div></div><div class="footer-col"><h4>EXPLORE</h4>${routes.map(([n,u])=>`<a href="${u}">${n}</a>`).join('')}</div><div class="footer-col"><h4>OUR ROBOTS</h4><a href="/robots/advertising">Z-01 Advertising Robot</a><a href="/robots/serving">Z-02 Serving Robot</a><a href="/robots/companion">Z-03 Companion Robot</a></div><div class="footer-col"><h4>CONTACT</h4><a href="tel:${PHONE.replace(/[^0-9+]/g,'')}">${esc(PHONE)}</a><a href="mailto:${esc(EMAIL)}">${esc(EMAIL)}</a><a href="https://wa.me/${PHONE_DIGITS}?text=Hello%20ZEVON%2C%20I%27d%20like%20to%20know%20more." target="_blank" rel="noopener">WhatsApp us ↗</a></div></div><div class="footer-bottom"><span>© 2026 ZEVON ENTERTAINMENT. All rights reserved.</span><div><a href="/privacy">Privacy Policy</a><a href="/terms">Terms &amp; Conditions</a></div></div></div></footer>`;}
function floatingChat(){return `<button class="chat-button" id="chat-button" aria-label="Open chat options"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.5a7.5 7.5 0 0 1-8 7.48 8 8 0 0 1-3.2-.67L4 20l1.68-3.66A7.25 7.25 0 0 1 4 11.5 7.5 7.5 0 0 1 12 4a7.5 7.5 0 0 1 8 7.5Z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M8 11.5h.01M12 11.5h.01M16 11.5h.01" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg></button><div class="chat-pop" id="chat-pop"><strong>Talk to our team</strong><p>Have a question about a robot, rental or demonstration?</p><a class="btn btn-small" href="https://wa.me/${PHONE_DIGITS}?text=Hello%20ZEVON%2C%20I%27d%20like%20to%20know%20more." target="_blank" rel="noopener">Chat on WhatsApp ↗</a></div>`;}
function cta(){return `<section class="cta-band"><div class="container"><span class="eyebrow">YOUR NEXT EXPERIENCE STARTS HERE</span><h2>Ready to Experience <span class="gold">Something Different?</span></h2><p>Let's find the right robotic solution for your event or business.</p><div class="hero-actions"><a class="btn" href="/contact?subject=Book%20a%20Demo">Book a Demo&nbsp; ↗</a><a class="btn btn-outline" href="/contact">Contact Us&nbsp; ↗</a></div><p class="phone-line">Or call us directly on <a href="tel:${PHONE.replace(/[^0-9+]/g,'')}"><strong>${esc(PHONE)}</strong></a></p></div></section>`;}
function robotCard(key,linkText='Explore'){const r=robots[key];return `<article class="solution-card reveal"><div class="product-art"><span class="robot-badge">${r.code}</span>${robotVisual(key)}</div><div class="solution-copy"><h3>${r.name}</h3><p class="tagline">${r.tagline}</p><p>${esc(r.description.split('.')[0])}.</p><ul class="mini-list">${r.features.slice(0,3).map(x=>`<li>${x}</li>`).join('')}</ul><a class="text-link" href="/robots/${key}">${linkText} ${r.name} <span>→</span></a></div></article>`;}
function robotCards(linkText){return `<div class="card-grid">${Object.keys(robots).map(k=>robotCard(k,linkText||'Explore')).join('')}</div>`;}
function sectionTitle(eyebrow,title,copy='',row=false){return `<div class="section-head ${row?'row':''} reveal"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}</div>${row?'<a class="text-link" href="/robots">View all robots <span>→</span></a>':''}</div>`;}
function heroHome(){const title=siteContent.hero_title||'Robotics That Transform Every Experience.';const split=title.lastIndexOf(' ');const first=split>0?title.slice(0,split):title;const last=split>0?title.slice(split+1):'';const image=`<img class="hero-photo" src="${esc(siteContent.images?.hero||'/assets/site-photos/mall-atrium.jpeg')}" alt="ZEVON advertising robot in a shopping mall" fetchpriority="high">`;return `<section class="hero"><div class="container hero-grid"><div class="hero-copy"><span class="eyebrow">ZEVON ENTERTAINMENT — ROBOTICS &amp; EVENT TECHNOLOGY</span><h1>${esc(first)} <span class="gold">${esc(last)}</span></h1><p>${esc(siteContent.hero_subtitle||'')}</p><div class="hero-actions"><a class="btn" href="/robots">Explore Our Robots&nbsp; →</a><a class="btn btn-outline" href="/rental">Rent a Robot</a></div><div class="hero-note"><i class="pulse"></i> Advertising · Serving · Companion</div></div><div class="hero-visual"><div class="hero-arch"><span class="arch-title">PREMIUM INNOVATION</span>${image}<div class="scene-grid"></div></div><div class="float-chip top">✦ &nbsp;No trays. Pure advertising.</div><div class="float-chip bottom"><strong>Now presenting</strong><span>Z-01 Advertising Robot</span></div></div></div></section>`;}
function ticker(){let words=['RENTALS','BRAND ACTIVATIONS','HOSPITALITY SERVICES','ADVERTISING ROBOTS','SERVING ROBOTS','COMPANION ROBOTS','EVENT RENTALS'];return `<div class="ticker" aria-label="ZEVON services"><div class="ticker-track">${[0,1].map(()=>words.map(w=>`<span>${w}</span><b>◆</b>`).join('')).join('')}</div></div>`;}
function processSection(){return `<section class="section dark"><div class="container">${sectionTitle('HOW IT WORKS','From First Hello to <span class="gold">Show Time.</span>','A clear, guided process from your first enquiry to the day of your event.') }<div class="steps">${steps.map(([n,t,d,i])=>`<article class="step-card reveal"><span class="step-num">${n}</span><div class="icon-orb">${i}</div><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section>`;}
function applicationCards(){return `<div class="scene-grid-cards">${applications.slice(0,4).map(([title,copy,key,a,b,scene],i)=>`<a class="scene-card reveal venue-card-home" href="/applications#venue-${i}">${venueArtwork(key,a,b,scene,i)}<div class="venue-copy"><span class="venue-kicker">VENUE CONCEPT</span><h3>${title}</h3><p>${copy}</p><span class="venue-link">Explore this venue&nbsp; ↗</span></div></a>`).join('')}</div>`;}
function home(){return `${heroHome()}${ticker()}<section class="section"><div class="container">${sectionTitle('WHO WE ARE','More Than Robots. <span class="gold">Better Experiences.</span>','ZEVON ENTERTAINMENT brings intelligent robotic solutions into real-world environments. Our robots help businesses attract attention, improve customer experiences and make events more engaging.')}<div class="card-grid">${[['◎','Smart Advertising','Robots that display your brand, play promotional content and pull a crowd at any venue.'],['◈','Intelligent Serving','Autonomous serving support for food, beverages and hospitality teams at events and venues.'],['✧','Interactive Experiences','Companion robots that entertain children and engage guests of all ages.']].map(([i,t,d],n)=>`<article class="feature-card reveal"><div class="icon-orb">${i}</div><h3>${t}</h3><p>${d}</p><span style="display:block;text-align:right;color:#d8ddcf;font:700 2rem Manrope">0${n+1} ↗</span></article>`).join('')}</div></div></section><section class="section dark"><div class="container">${sectionTitle('OUR ROBOTS','Explore Our <span class="gold">Robotic Solutions</span>','Three distinct robots. One thoughtful approach to making everyday experiences more engaging.',true)}${robotCards('Explore')}</div></section><section class="section"><div class="container split"><div class="split-copy reveal"><span class="eyebrow">RENTAL SERVICES</span><h2>Bring Robotics to <span class="gold">Your Next Event.</span></h2><p class="muted" style="margin-top:18px">Make your event more memorable with ZEVON's robotic rental solutions. Create engaging experiences for your guests while giving your brand a unique presence.</p><div class="chips">${['Weddings & receptions','Corporate events','Exhibitions & trade fairs','Product launches','Shopping malls','Promotional campaigns','Private celebrations'].map(x=>`<span class="chip">${x}</span>`).join('')}</div><a class="btn" href="/rental">Enquire About Rental&nbsp; →</a></div><div class="split-visual reveal">${robotArt('serving')}<span class="float-chip top">Z-02 &nbsp;·&nbsp; Hospitality support</span></div></div></section><section class="section light-band"><div class="container split"><div class="split-visual group reveal"><img class="robot-group-photo" src="/assets/site-photos/robot-lineup.jpeg" alt="ZEVON advertising, serving and companion robots together" loading="lazy"></div><div class="split-copy reveal"><span class="eyebrow">PURCHASE SOLUTIONS</span><h2>Own the Future of <span class="gold">Intelligent Experiences.</span></h2><p class="muted" style="margin-top:18px">Looking to integrate robotics into your business? Explore our robots for commercial applications and discover how intelligent automation can support your operations.</p><div class="contact-stack" style="margin:20px 0">${Object.entries(robots).map(([k,r])=>`<a class="contact-card" href="/robots/${k}"><span class="icon-orb">↗</span><strong>${r.code} ${r.name}</strong><span style="margin-left:auto">↗</span></a>`).join('')}</div><a class="btn" href="/purchase">Enquire About Purchase&nbsp; →</a></div></div></section><section class="section"><div class="container">${sectionTitle('APPLICATIONS','Where Our Robots <span class="gold">Make a Difference</span>','')} ${applicationCards()}</div></section>${processSection()}<section class="section"><div class="container">${sectionTitle('WHY ZEVON','Why Choose <span class="gold">ZEVON?</span>','We bring thoughtful robotic solutions together with practical guidance and personal support.') }<div class="card-grid">${values.map(([t,d])=>`<article class="feature-card reveal"><div class="icon-orb">✓</div><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section>${cta()}${footer()}`;}
function pageHero(eyebrow,title,copy,art='advertising',actions=''){return `<section class="page-hero"><div class="container page-hero-grid"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${copy}</p>${actions}</div><div class="hero-visual"><div class="hero-arch"><span class="arch-title">ZEVON ROBOTICS</span>${robotVisual(art)}</div></div></div></section>`;}
function robotOverview(){return `${pageHero('OUR ROBOTS','Three Robots. <span class="gold">Every Occasion.</span>','Each ZEVON robot is built for a different role — advertising your brand, serving your guests, or entertaining the youngest visitors. Explore each one and find the right fit for your event or business.','advertising',`<div class="hero-actions"><a class="btn" href="/contact?subject=Book%20a%20Demo">Book a Demo&nbsp; ↗</a><a class="btn btn-outline" href="/rental">Explore Rental</a></div>`)}<section class="section"><div class="container">${sectionTitle('OUR ROBOTS','Find the right fit for <span class="gold">your venue.</span>')}${robotCards('View details')}<div class="white-card" style="margin-top:26px"><h3>Popular event types</h3><div class="chips">${['Weddings & receptions','Corporate events','Exhibitions & trade fairs','Product launches','Shopping malls','Promotional campaigns','Private celebrations'].map(x=>`<span class="chip">${x}</span>`).join('')}</div></div></div></section>${cta()}${footer()}`;}
function robotDetail(key){let r=robots[key];return `${pageHero(`${r.code} — ZEVON ROBOTICS`,`Meet the ZEVON <span class="gold">${r.name}</span>`,`${r.tagline} ${r.description}`,key,`<div class="hero-actions"><a class="btn" href="/contact?subject=Book%20a%20Demo">Book a Demonstration</a><a class="btn btn-outline" href="/rental">Enquire to Rent</a><a class="btn btn-outline" href="/purchase">Enquire to Purchase</a></div>`)}<section class="section"><div class="container">${sectionTitle('MAIN FEATURES',`Designed to be <span class="gold">${key==='advertising'?'noticed':key==='serving'?'helpful':'welcoming'}.</span>`,r.look)}<div class="split"><div class="reveal"><div class="spec-note"><strong>Specifications: coming soon</strong><span>Detailed technical specifications will be published soon. For current details, demonstrations and pricing, contact our team directly. We only publish confirmed details. Full spec sheets are available on request.</span></div></div><div class="detail-feature-grid">${r.features.map(x=>`<div class="detail-feature reveal"><i>✓</i><strong>${x}</strong></div>`).join('')}</div></div></div></section><section class="section dark"><div class="container">${sectionTitle('APPLICATIONS','Where this robot <span class="gold">shines.</span>') }<div class="chips">${r.uses.map(x=>`<span class="chip">${x}</span>`).join('')}</div></div></section><section class="section"><div class="container">${sectionTitle('IN THE WILD',`${r.short} Robot at <span class="gold">work.</span>`)}<div class="gallery">${r.gallery.map((x,i)=>scene(x,key,i)).join('')}</div></div></section><section class="section"><div class="container"><div class="white-card dark reveal" style="padding:50px;display:flex;justify-content:space-between;align-items:center;gap:30px"><div><span class="eyebrow">${r.code} ${r.name.toUpperCase()}</span><h2 style="font-size:clamp(2rem,4vw,3.2rem)">Interested in the <span class="gold">${r.code}?</span></h2><p>Rent it for your next event, purchase it for your business, or book a live demonstration.</p></div><div class="hero-actions"><a class="btn" href="/contact?subject=Book%20a%20Demo">Book a Demo</a><a class="btn btn-outline" href="/rental">Rental Enquiry →</a></div></div></div></section>${cta()}${footer()}`;}
function scene(title,key='advertising',i=0){const colors=[['#8c6b50','#1d3b33'],['#78654d','#243c33'],['#7c8a7e','#19352e'],['#9b7654','#18342e']][i%4];return `<article class="scene-card" style="--scene-a:${colors[0]};--scene-b:${colors[1]}"><div class="scene-art">${robotVisual(key)}</div><div><h3>${title}</h3></div></article>`;}
function rental(){return `${pageHero('RENTAL','Make your next event <span class="gold">unforgettable.</span>',"Renting a ZEVON robot brings a premium, memorable experience to your event — serving your guests and entertaining every age group. Tell us about your event and we'll handle the rest.",'serving',`<div class="hero-actions"><a class="btn" href="#rental-form">Enquire About Rental&nbsp; →</a></div>`)}<section class="section"><div class="container">${sectionTitle('AVAILABLE FOR RENTAL','Choose the robot that fits <span class="gold">your occasion.</span>')}${robotCards('View details')}<div class="white-card" style="margin-top:24px"><h3>Popular event types</h3><div class="chips">${['Weddings & receptions','Corporate events','Exhibitions & trade fairs','Product launches','Shopping malls','Promotional campaigns','Private celebrations'].map(x=>`<span class="chip">${x}</span>`).join('')}</div></div></div></section>${processSection()}${enquirySection('rental')}${cta()}${footer()}`;}
function purchase(){return `${pageHero('PURCHASE','Bring Intelligent Robotics <span class="gold">into Your Business.</span>','ZEVON robots are built for commercial environments — exhibitions, malls, hotels, restaurants and corporate spaces. Request details, arrange a demonstration and explore what a robot can do for your operations.','advertising',`<div class="hero-actions"><a class="btn" href="#purchase-form">Request Purchase Details&nbsp; →</a></div>`)}<section class="section"><div class="container">${sectionTitle('AVAILABLE FOR PURCHASE','Explore the ZEVON <span class="gold">robot range.</span>')}${robotCards('Enquire about this robot')}<p class="muted" style="text-align:center;margin-top:22px">Pricing is provided on request and tailored to the venue and need.</p></div></section><section class="section light-band"><div class="container">${sectionTitle('WHY BUSINESSES CHOOSE ZEVON','Commercially practical. <span class="gold">Genuinely different.</span>')}<div class="card-grid">${values.map(([t,d])=>`<article class="feature-card reveal"><div class="icon-orb">✓</div><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section>${enquirySection('purchase')}${cta()}${footer()}`;}
function inputField(label,name,type='text',opts={}){const required=opts.required!==false,req=required?' required':'';let ctl=type==='select'?`<select id="${name}" name="${name}"${req}><option value="">Select ${label.toLowerCase()}</option>${opts.options.map(x=>`<option>${x}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="${name}" name="${name}" placeholder="${opts.placeholder||''}"${req}></textarea>`:`<input id="${name}" name="${name}" type="${type}" placeholder="${opts.placeholder||''}"${req} ${type==='email'?'autocomplete="email"':''}>`;return `<div class="field ${opts.full?'full':''}"><label for="${name}">${label}${required?' *':''}</label>${ctl}</div>`;}
function inquiryForm(type){let fields;if(type==='rental')fields=[['Name','name','text'],['Phone number','phone','tel'],['Email','email','email'],['Event type','event_type','select',{options:['Wedding','Corporate event','Exhibition/Trade fair','Product launch','Shopping mall','Promotional campaign','Private celebration','Other']}],['Event date','event_date','date'],['Event location','location','text',{placeholder:'City / venue'}],['Robot required','robot','select',{options:['Z-01 Advertising Robot','Z-02 Serving Robot','Z-03 Companion Robot','Not sure']}],['Duration','duration','text',{placeholder:'e.g. 1 day, 3 hours, full weekend'}],['Additional requirements','message','textarea',{placeholder:'Guest count, venue details, display content, timings — anything that helps us prepare',full:true,required:false}]];
  else if(type==='purchase')fields=[['Name','name','text'],['Company name','company','text',{required:false}],['Phone number','phone','tel'],['Email','email','email'],['Robot interested in','robot','select',{options:['Z-01 Advertising Robot','Z-02 Serving Robot','Z-03 Companion Robot','Not sure']}],['Business type','business_type','select',{options:['Events & exhibitions','Retail','Hospitality','Corporate','Other']}],['Location','location','text',{placeholder:'City, country'}],['Additional requirements','message','textarea',{placeholder:'Intended use, venues, operating hours — anything that helps us advise you.',full:true,required:false}]];
  else fields=[['Name','name','text'],['Email','email','email'],['Mobile number','phone','tel'],['Subject','subject','select',{options:['Book a Demo','Rental enquiry','Purchase enquiry','General question']}],['Event date','event_date','date'],['Available time for a call','call_time','select',{options:['Morning (9 am–12 pm)','Afternoon (12 pm–4 pm)','Evening (4 pm–7 pm)']}],['Description (optional)','message','textarea',{placeholder:'Tell us a little about your event or business (optional)',full:true,required:false}]];
  const title=type==='rental'?'Rental Enquiry':type==='purchase'?'Purchase Enquiry':'Send us an enquiry';const btn=type==='rental'?'Submit Rental Enquiry':type==='purchase'?'Request Purchase Details':'Send Enquiry';return `<form class="form-card enquiry-form" data-kind="${type}" novalidate><h3>${title}</h3><p>We usually respond within one business day.</p><div class="form-grid">${fields.map(([l,n,t,o])=>inputField(l,n,t,o||{})).join('')}<div class="hidden-trap" aria-hidden="true"><label for="website">Leave this empty</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div></div><button class="btn" type="submit">${btn}&nbsp; ↗</button><div class="form-msg" aria-live="polite"></div></form>`;}
function enquirySection(type){let rentalType=type==='rental',title=rentalType?'Tell us about <span class="gold">your event.</span>':'Request <span class="gold">purchase details.</span>';let copy=rentalType?'Fill in the form and our team will contact you with availability, a tailored quote and suggestions for your venue.':'Tell us about your business and how you plan to use the robot. Our team will respond with purchase details, pricing and delivery options — or arrange a live demonstration first.';let bullets=rentalType?['A tailored response within one business day','Robot recommendations for your venue and audience','Display content support for advertising robots','Delivery, setup and on-site support included']:['Purchase details tailored to your business','Live demonstration on request','Delivery and on-site onboarding','Personalised customer support after purchase'];return `<section class="section form-section" id="${type}-form"><div class="container form-layout"><div><span class="eyebrow">${rentalType?'RENTAL ENQUIRY':'PURCHASE ENQUIRY'}</span><h2>${title}</h2><p class="muted" style="margin-top:18px">${copy}</p><ul class="benefit-list">${bullets.map(x=>`<li>${x}</li>`).join('')}</ul><a class="btn btn-small" href="tel:${PHONE.replace(/[^0-9+]/g,'')}">☎ &nbsp;${esc(PHONE)}</a> <a class="btn btn-outline btn-small" href="https://wa.me/${PHONE_DIGITS}" target="_blank" rel="noopener">WhatsApp ↗</a></div>${inquiryForm(type)}</div></section>`;}
function contact(){return `${pageHero('CONTACT',"Let's Talk About <span class=\"gold\">Your Event or Business.</span>",'Questions about rentals, purchases, demonstrations or customised robotic solutions — our team is one message away.','companion')}<section class="section"><div class="container form-layout"><div><span class="eyebrow">REACH US DIRECTLY</span><h2>Our team is <span class="gold">one message away.</span></h2><div class="contact-stack"><a class="contact-card" href="tel:${PHONE.replace(/[^0-9+]/g,'')}"><span class="icon-orb">☎</span><span><small>CALL US</small><strong>${esc(PHONE)}</strong></span></a><a class="contact-card" href="mailto:${esc(EMAIL)}"><span class="icon-orb">✉</span><span><small>EMAIL US</small><strong>${esc(EMAIL)}</strong></span></a><a class="contact-card" href="https://wa.me/${PHONE_DIGITS}" target="_blank" rel="noopener"><span class="icon-orb">◌</span><span><small>WHATSAPP</small><strong>Chat with us instantly</strong></span><span style="margin-left:auto;color:#9b8049">OPEN ↗</span></a><div class="contact-card"><span class="icon-orb">⌖</span><span><small>LOCATION</small><strong>Business location will be published here soon.</strong></span></div></div><p class="eyebrow" style="margin-top:24px">FOLLOW US</p><div class="social-links" aria-label="Social profiles"><a href="https://www.youtube.com/" target="_blank" rel="noopener noreferrer" aria-label="ZEVON on YouTube demo link">▶ <span>YouTube</span></a><a href="https://www.linkedin.com/" target="_blank" rel="noopener noreferrer" aria-label="ZEVON on LinkedIn demo link"><b>in</b> <span>LinkedIn</span></a><a href="https://www.instagram.com/" target="_blank" rel="noopener noreferrer" aria-label="ZEVON on Instagram demo link">◎ <span>Instagram</span></a></div></div>${inquiryForm('contact')}</div></section>${cta()}${footer()}`;}
function about(){return `${pageHero('ABOUT ZEVON','More Than Robots. <span class="gold">Better Experiences.</span>','ZEVON ENTERTAINMENT brings intelligent robotic solutions into real-world environments — helping businesses attract attention, improve customer experiences and make events more engaging.','advertising')}<section class="section"><div class="container split"><div class="split-copy"><span class="eyebrow">OUR APPROACH</span><h2>Thoughtful technology. <span class="gold">Human moments.</span></h2><p class="muted" style="margin-top:18px">We connect advertising, hospitality and customer engagement with a practical range of robots. Each solution is shaped around the venue, audience and goals you share with our team.</p><p class="muted">We publish confirmed information only. Ask us directly for current availability, demonstrations and technical details.</p><a class="btn" href="/contact?subject=Book%20a%20Demo">Talk to our team ↗</a></div><div class="split-visual group">${robotVisual('advertising')}${robotVisual('serving')}${robotVisual('companion')}</div></div></section><section class="section light-band"><div class="container">${sectionTitle('WHAT MATTERS TO US','Innovation with <span class="gold">care and clarity.</span>')}<div class="card-grid">${[['Innovation','Bring modern robotic experiences into familiar places.'],['Reliability','Plan thoughtfully with our team around your venue and schedule.'],['Guest experience','Make every interaction welcoming, useful and memorable.']].map(([t,d])=>`<article class="feature-card"><div class="icon-orb">✦</div><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section>${processSection()}${cta()}${footer()}`;}
function applicationsPage(){return `${pageHero('APPLICATIONS','Robots made for <span class="gold">real places.</span>','Explore original venue concepts showing how ZEVON robots can fit naturally into the spaces where people gather. Tap a venue to view its concept and plan an enquiry.','advertising')}<section class="section"><div class="container">${sectionTitle('VENUE CONCEPTS','See ZEVON in <span class="gold">your kind of place.</span>','Original illustrated scenes for distinct venues. Each concept includes a robot recommendation and a direct path to a tailored rental enquiry.')}<div class="scene-grid-cards venue-grid">${applications.map(([title,copy,key,a,b,scene,eventType],i)=>`<article class="scene-card reveal venue-card" id="venue-${i}">${venueArtwork(key,a,b,scene,i)}<div class="venue-copy"><span class="venue-kicker">VENUE CONCEPT · 0${i+1}</span><h3>${title}</h3><p>${copy}</p><div class="venue-card-bottom"><span>Best fit: ${robots[key].code} ${robots[key].short}</span><button type="button" class="venue-open" data-venue="${i}">View concept&nbsp; ↗</button></div></div></article>`).join('')}</div><dialog class="venue-dialog" id="venue-dialog" aria-label="Venue concept details"><div class="venue-dialog-content" id="venue-dialog-content"></div></dialog></div></section>${cta()}${footer()}`;}
function legal(kind){let privacy=kind==='privacy';return `${pageHero(privacy?'PRIVACY POLICY':'TERMS & CONDITIONS',privacy?'Your information, <span class="gold">handled with care.</span>':'Clear information. <span class="gold">Thoughtful service.</span>',privacy?'We use the details you submit to respond to your enquiry and help with your request.':'These terms describe the information available on this website. Rental and purchase details are confirmed in writing.','companion')}<section class="section"><div class="container legal-copy"><span class="eyebrow">LAST UPDATED · NOVEMBER 2026</span>${privacy?`<h2>Information we collect</h2><p>When you send an enquiry, you may share your name, phone number, email address and information about your event or business. We use these details to respond to your enquiry and provide the information you request.</p><h2>How we use your information</h2><p>Submitted information is used only to reply to enquiries, discuss robot demonstrations, rental or purchase options, and coordinate a request you have made. We do not sell enquiry details.</p><h2>Retention and contact</h2><p>We retain enquiry details for as long as needed to respond and maintain relevant business records. To ask about information you have shared, contact <a href="mailto:${EMAIL}">${EMAIL}</a>.</p><h2>Updates</h2><p>This notice may be updated as the website and services develop. Please review the page for the current version.</p>`:`<h2>Website information</h2><p>Robot descriptions on this website are general information. Technical specifications, availability, pricing and suitability are confirmed directly with ZEVON before any booking or purchase.</p><h2>Enquiries and bookings</h2><p>Sending an enquiry does not confirm a booking or purchase. Rental and purchase terms, pricing, delivery and availability are confirmed in writing by our team.</p><h2>Accuracy</h2><p>We aim to keep website information accurate and current. Product details may change as confirmed information becomes available.</p><h2>Contact</h2><p>For questions about these terms, contact <a href="mailto:${EMAIL}">${EMAIL}</a>.</p>`}</div></section>${cta()}${footer()}`;}
